<?php
require_once '../config/auth.php';require_role('admin');$pdo=db();$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='delete'){$q=$pdo->prepare('DELETE FROM jadwal WHERE id_jadwal=?');$q->execute([(int)$_POST['id_jadwal']]);flash('success','Jadwal dihapus.');}else{$data=[(int)$_POST['id_guru'],(int)$_POST['id_mapel'],(int)$_POST['id_kelas'],$_POST['hari'],$_POST['jam_mulai'],$_POST['jam_selesai'],trim($_POST['ruang']??'')?:null];if($data[4]>=$data[5])throw new InvalidArgumentException('Jam selesai harus lebih besar dari jam mulai.');if(!empty($_POST['id_jadwal'])){$q=$pdo->prepare('UPDATE jadwal SET id_guru=?,id_mapel=?,id_kelas=?,hari=?,jam_mulai=?,jam_selesai=?,ruang=? WHERE id_jadwal=?');$q->execute([...$data,(int)$_POST['id_jadwal']]);}else{$q=$pdo->prepare('INSERT INTO jadwal(id_guru,id_mapel,id_kelas,hari,jam_mulai,jam_selesai,ruang) VALUES(?,?,?,?,?,?,?)');$q->execute($data);}flash('success','Jadwal berhasil disimpan.');}redirect('jadwal.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Jadwal gagal disimpan. Periksa data dan benturan jadwal.';}}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM jadwal WHERE id_jadwal=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$teachers=$pdo->query('SELECT id_guru,nama_guru FROM guru ORDER BY nama_guru')->fetchAll();$maps=$pdo->query('SELECT id_mapel,nama_mapel FROM mata_pelajaran ORDER BY nama_mapel')->fetchAll();$classes=$pdo->query('SELECT id_kelas,nama_kelas FROM kelas ORDER BY nama_kelas')->fetchAll();$rows=$pdo->query('SELECT j.*,g.nama_guru,mp.nama_mapel,k.nama_kelas FROM jadwal j JOIN guru g ON g.id_guru=j.id_guru JOIN mata_pelajaran mp ON mp.id_mapel=j.id_mapel JOIN kelas k ON k.id_kelas=j.id_kelas ORDER BY FIELD(j.hari,"Senin","Selasa","Rabu","Kamis","Jumat"),j.jam_mulai')->fetchAll();$page_title='Jadwal Pelajaran';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><h2>Jadwal Pelajaran</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-3 mb-4"><form method="post" class="row g-2 align-items-end"><?=csrf_field()?><input type="hidden" name="id_jadwal" value="<?=e($edit['id_jadwal']??'')?>"><div class="col-md-2"><label>Guru</label><select class="form-select" name="id_guru" required><option value="">Pilih...</option><?php foreach($teachers as $x):?><option value="<?=$x['id_guru']?>" <?=($edit['id_guru']??'')==$x['id_guru']?'selected':''?>><?=e($x['nama_guru'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Mapel</label><select class="form-select" name="id_mapel" required><option value="">Pilih...</option><?php foreach($maps as $x):?><option value="<?=$x['id_mapel']?>" <?=($edit['id_mapel']??'')==$x['id_mapel']?'selected':''?>><?=e($x['nama_mapel'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Kelas</label><select class="form-select" name="id_kelas" required><option value="">Pilih...</option><?php foreach($classes as $x):?><option value="<?=$x['id_kelas']?>" <?=($edit['id_kelas']??'')==$x['id_kelas']?'selected':''?>><?=e($x['nama_kelas'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Hari</label><select class="form-select" name="hari"><?php foreach(['Senin','Selasa','Rabu','Kamis','Jumat'] as $day):?><option <?=($edit['hari']??'Senin')===$day?'selected':''?>><?=$day?></option><?php endforeach;?></select></div><div class="col-md-1"><label>Mulai</label><input class="form-control" type="time" name="jam_mulai" value="<?=e($edit['jam_mulai']??'')?>" required></div><div class="col-md-1"><label>Selesai</label><input class="form-control" type="time" name="jam_selesai" value="<?=e($edit['jam_selesai']??'')?>" required></div><div class="col-md-1"><label>Ruang</label><input class="form-control" name="ruang" value="<?=e($edit['ruang']??'')?>"></div><div class="col-md-1"><button class="btn btn-primary w-100"><?= $edit?'Ubah':'Tambah'?></button></div></form></div><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Hari/Jam</th><th>Mapel</th><th>Guru</th><th>Kelas</th><th>Ruang</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['hari'].' '.substr($r['jam_mulai'],0,5))?></td><td><?=e($r['nama_mapel'])?></td><td><?=e($r['nama_guru'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=e($r['ruang']??'-')?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id_jadwal']?>">Edit</a><form method="post" class="d-inline" onsubmit="return confirm('Hapus jadwal ini?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id_jadwal" value="<?=$r['id_jadwal']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require '../includes/footer.php';
